 channelId: string): Avail[] {\n  const lines = manifest.split(\"\\n\");\n\n  let mediaSequence = 0;\n  let lastPdt: string | undefined;\n  let blockBreakId: string | undefined;\n  const avails: Avail[] = [];\n\n  let open: {\n    startLine: number;\n    startSequence: number;\n    declaredDuration?: number;\n    measuredDuration: number;\n    pdt?: string;\n    externalBreakId?: string;\n  } | null = null;\n\n  let midBreakDuration = 0;\n  let midBreakExternalId: string | undefined;\n  let midBreakStartLine = 0;\n  let midBreakStartSequence = 0;\n\n  for (let i = 0; i < lines.length; i++) {\n    const line = lines[i]!;\n    const trimmed = line.trim();\n\n    const seqMatch = trimmed.match(MEDIA_SEQUENCE);\n    if (seqMatch) {\n      mediaSequence = Number(seqMatch[1]);\n      if (!open && midBreakDuration === 0) {\n        midBreakStartSequence = mediaSequence;\n        midBreakStartLine = i;\n      }\n      continue;\n    }\n\n    const pdtMatch = trimmed.match(PROGRAM_DATE_TIME);\n    if (pdtMatch) {\n      lastPdt = pdtMatch[1]!.trim();\n      continue;\n    }\n\n    const marker = parseMarkerLine(line, i);\n    if (marker?.kind === \"daterange\" && marker.id) {\n      blockBreakId = marker.id;\n      if (open && open.externalBreakId === undefined) open.externalBreakId = marker.id;\n      if (!open && midBreakExternalId === undefined) midBreakExternalId = marker.id;\n      continue;\n    }\n    if (marker?.kind === \"cue_out\" && !open) {\n      open = {\n        startLine: i,\n        startSequence: mediaSequence,\n        measuredDuration: 0,\n        ...(marker.duration === undefined ? {} : { declaredDuration: marker.duration }),\n        ...(lastPdt === undefined ? {} : { pdt: lastPdt }),\n        ...(blockBreakId === undefined ? {} : { externalBreakId: blockBreakId }),\n      };\n      midBreakDuration = 0;\n      continue;\n    }\n    if (marker?.kind === \"cue_in\") {\n      if (open) {\n        const declared = open.declaredDuration;\n        const extId = open.externalBreakId;\n        const startSeq = open.startSequence;\n        avails.push({\n          opportunityId: extId ? `opp_${channelId}_${extId}` : `opp_${channelId}_${startSeq}`,\n          channelId,\n          ...(extId === undefined ? {} : { externalBreakId: extId }),\n          duration: declared ?? open.measuredDuration,\n          ...(declared === undefined ? {} : { declaredDuration: declared }),\n          measuredDuration: open.measuredDuration,\n          startSequence: startSeq,\n          ...(open.pdt === undefined ? {} : { programDateTime: open.pdt }),\n          startLine: open.startLine,\n          endLine: i,\n        });\n        open = null;\n      } else if (midBreakDuration > 0) {\n        const extId = midBreakExternalId;\n        const startSeq = midBreakStartSequence;\n        avails.push({\n          opportunityId: extId ? `opp_${channelId}_${extId}` : `opp_${channelId}_${startSeq}`,\n          channelId,\n          ...(extId === undefined ? {} : { externalBreakId: extId }),\n          duration: midBreakDuration,\n          measuredDuration: midBreakDuration,\n          startSequence: startSeq,\n          startLine: midBreakStartLine,\n          endLine: i,\n        });\n        midBreakDuration = 0;\n        midBreakExternalId = undefined;\n      }\n      continue;\n    }\n\n    const infMatch = trimmed.match(EXTINF);\n    if (infMatch) {\n      const segDur = Number(infMatch[1]);\n      if (open) {\n        open.measuredDuration += segDur;\n      } else {\n        if (midBreakDuration === 0) {\n          midBreakStartSequence = mediaSequence;\n          midBreakStartLine = i;\n        }\n        midBreakDuration += segDur;\n      }\n    } else if (trimmed.length > 0 && !trimmed.startsWith(\"#\")) {\n      mediaSequence += 1;\n      blockBreakId = undefined;\n    }\n  }\n\n  return avails;\n}\nEOF\n",
